def check_expression(expression):
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in expression:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack or stack[-1] != bracket_map[char]:
                return False
            stack.pop()

    return len(stack) == 0

assert check_expression("{()}[{}]") == True
